$error='';$notice=$_SESSION['notice']??'';unset($_SESSION['notice']);
function done(string $section,string $message): never {$_SESSION['notice']=$message;header('Location: /admin/?section='.$section);exit;}
function editor_direction(string $name):string{return ($GLOBALS['type']??'')==='book'&&($GLOBALS['bookLang']??'en')==='ar'&&in_array($name,['title','subtitle','category','author','intro','body','ending'],true)?' lang="ar" dir="rtl"':'';}
function field(string $name,string $label,string $value='',string $type='text'): string{return '<label>'.h($label).'<input'.editor_direction($name).' name="'.h($name).'" type="'.h($type).'" value="'.h($value).'"></label>';}
function area(string $name,string $label,string $value='',int $rows=8): string{return '<label>'.h($label).'<textarea'.editor_direction($name).' name="'.h($name).'" rows="'.$rows.'">'.h($value).'</textarea></label>';}
function image_select(string $value=''): string{
    $s='<label>Photo, artwork, or book cover<select name="image"><option value="">None</option>';
    foreach(['images','book-covers','uploads'] as $folder)foreach(['webp','png','jpg','jpeg'] as $extension)foreach(glob(dirname(__DIR__).'/assets/'.$folder.'/*.'.$extension)?:[] as $file){if(str_contains($file,'-640.'))continue;$v='assets/'.$folder.'/'.basename($file);$s.='<option value="'.h($v).'"'.($v===$value?' selected':'').'>'.h($folder.' / '.basename($file)).'</option>';}
    return $s.'</select></label>';
}
function action_form(string $action,int $id,string $label,bool $danger=false): string{return '<form method="post"'.($danger?' data-confirm="Delete this item permanently?"':'').'>'.csrf().'<input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="id" value="'.$id.'"><button class="'.($danger?'danger':'secondary').'">'.h($label).'</button></form>';}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=$_POST['action']??'';
    try{
        if($action==='save_post'){
            $type=$_POST['type']??'';$slug=trim($_POST['slug']??'');$title=trim($_POST['title']??'');$status=$_POST['status']??'draft';$date=$_POST['published_at']??date('Y-m-d');
            $reserved=['index','about','work','contact','gallery','books','book-summaries','articles','notes','science','technology','business','travel','personal','privacy','credits','404','article','admin-preview'];
            if(!in_array($type,['article','book'],true)||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$slug)||strlen($slug)>140||in_array($slug,$reserved,true))throw new RuntimeException('Use a unique URL slug with lowercase letters, numbers, and hyphens.');
            if($title===''||unicode_length($title)>200||!in_array($status,['draft','published'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!strtotime($date))throw new RuntimeException('Check title, status, and date.');
            $image=$_POST['image']??'';if($image!==''&&!safe_image($image))throw new RuntimeException('Select an image from the media library.');
            $src=trim($_POST['source_url']??'');if($src!==''&&(!filter_var($src,FILTER_VALIDATE_URL)||parse_url($src,PHP_URL_SCHEME)!=='https'))throw new RuntimeException('Source URLs must use HTTPS.');
            $body=$_POST['body']??'';if(strlen($body)>250000)throw new RuntimeException('Keep main text under 250,000 bytes.');
            $values=[$type,$slug,$title,unicode_cut(trim($_POST['subtitle']??''),2000),unicode_cut(trim($_POST['category']??''),80),unicode_cut(trim($_POST['author']??''),150),$image,unicode_cut(trim($_POST['intro']??''),10000),$body,unicode_cut(trim($_POST['ending']??''),20000),$src,unicode_cut(trim($_POST['isbn']??''),32),$status,$date];
            db()->beginTransaction();$id=(int)($_POST['id']??0);if($id){$values[]=$id;q('UPDATE aa_posts SET type=?,slug=?,title=?,subtitle=?,category=?,author=?,image=?,intro=?,body=?,ending=?,source_url=?,isbn=?,status=?,published_at=? WHERE id=?',$values);}else q('INSERT INTO aa_posts(type,slug,title,subtitle,category,author,image,intro,body,ending,source_url,isbn,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$values);
            if(!$id)$id=(int)db()->lastInsertId();
            save_post_language($id,$type==='book'&&($_POST['language']??'en')==='ar'?'ar':'en');
            if($type==='article'&&array_key_exists('title_ar',$_POST))save_translation($id,$_POST);
            db()->commit();
            done($type==='book'?'books':'articles',$status==='published'?'Published. The public blog is updated.':'Draft saved, hidden from visitors.');
        }elseif($action==='save_video'){
            $id=youtube_id(trim($_POST['youtube_url']??''));$title=trim($_POST['title']??'');$image=$_POST['image']??'';
            if(!$id||!$title||unicode_length($title)>200||!safe_image($image))throw new RuntimeException('Use a valid HTTPS YouTube watch URL, a title, and a local poster image.');
            $items=watch_videos();$v=['id'=>$id,'title'=>$title,'description'=>unicode_cut(trim($_POST['description']??''),1000),'creator'=>unicode_cut(trim($_POST['creator']??''),100),'image'=>$image];$index=(int)($_POST['id']??-1);
            if($index>=0){if(!isset($items[$index]))throw new RuntimeException('This video no longer exists.');$items[$index]=$v;}else{if(count($items)>=12)throw new RuntimeException('Keep the homepage collection to 12 videos or fewer.');$items[]=$v;}
            save_setting('watch_videos',json_encode(array_values($items),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));done('videos','Video collection updated.');
        }elseif($action==='delete_video'){
            $items=watch_videos();unset($items[(int)($_POST['id']??-1)]);save_setting('watch_videos',json_encode(array_values($items),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));done('videos','Video removed from the homepage collection.');
        }elseif($action==='delete_post'){q('DELETE FROM aa_translations WHERE post_id=?',[(int)$_POST['id']]);q('DELETE FROM aa_post_languages WHERE post_id=?',[(int)$_POST['id']]);q('DELETE FROM aa_posts WHERE id=?',[(int)$_POST['id']]);done($section,'Entry deleted.');}
        elseif($action==='save_gallery'){
            $im=$_POST['image']??'';if(!safe_image($im)||trim($_POST['title']??'')===''||trim($_POST['alt']??'')==='')throw new RuntimeException('Choose an image, title, and descriptive alt text.');
            $v=[$im,unicode_cut(trim($_POST['title']),200),unicode_cut(trim($_POST['alt']),500),unicode_cut(trim($_POST['category']??''),80),(int)($_POST['sort_order']??0)];$id=(int)($_POST['id']??0);
            if($id){$v[]=$id;q('UPDATE aa_gallery SET image=?,title=?,alt=?,category=?,sort_order=? WHERE id=?',$v);}else q('INSERT INTO aa_gallery(image,title,alt,category,sort_order) VALUES(?,?,?,?,?)',$v);if(!$id)$id=(int)db()->lastInsertId();if(isset($_POST['title_ar'])){q('DELETE FROM aa_gallery_translations WHERE gallery_id=?',[$id]);q('INSERT INTO aa_gallery_translations(gallery_id,title,alt,category) VALUES(?,?,?,?)',[$id,unicode_cut(trim($_POST['title_ar']),200),unicode_cut(trim($_POST['alt_ar']??''),500),unicode_cut(trim($_POST['category_ar']??''),80)]);}done('gallery','Gallery updated in both languages.');
        }elseif($action==='delete_gallery'){q('DELETE FROM aa_gallery_translations WHERE gallery_id=?',[(int)$_POST['id']]);q('DELETE FROM aa_gallery WHERE id=?',[(int)$_POST['id']]);done('gallery','Gallery entry removed. Its media file is preserved.');}
        elseif($action==='upload'){
            $f=$_FILES['illustration']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024)throw new RuntimeException('Choose an image smaller than 8 MB.');
            $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$sz=@getimagesize($f['tmp_name']);
            if(!in_array($mime,['image/png','image/jpeg','image/webp'],true)||!$sz||max($sz[0],$sz[1])>6000||$sz[0]*$sz[1]>20000000)throw new RuntimeException('Use PNG, JPEG, or WebP up to 6000 pixels per side and 20 megapixels.');
            if(!function_exists('imagecreatefromstring')||!function_exists('imagewebp'))throw new RuntimeException('Enable PHP GD with WebP support in Hostinger to upload images.');
            $im=@imagecreatefromstring(file_get_contents($f['tmp_name']));if(!$im)throw new RuntimeException('The image could not be decoded.');
            $scale=min(1,1600/max($sz[0],$sz[1]));$w=max(1,(int)round($sz[0]*$scale));$ht=max(1,(int)round($sz[1]*$scale));$out=imagecreatetruecolor($w,$ht);imagealphablending($out,false);imagesavealpha($out,true);imagecopyresampled($out,$im,0,0,0,0,$w,$ht,$sz[0],$sz[1]);
            if(!imagewebp($out,dirname(__DIR__).'/assets/uploads/'.bin2hex(random_bytes(16)).'.webp',86))throw new RuntimeException('Check uploads-folder write permissions.');imagedestroy($out);imagedestroy($im);done('media','Image uploaded and optimized. Select it in a post or gallery entry.');
        }elseif($action==='save_pages'){
            foreach(['hero_title','hero_intro','about_title','about_body','work_body','hero_title_ar','hero_intro_ar','about_title_ar','about_body_ar','work_body_ar'] as $key)if(array_key_exists($key,$_POST))save_setting($key,unicode_cut(trim($_POST[$key]),100000));done('pages','Pages updated.');
        }elseif($action==='save_settings'){
            $email=trim($_POST['contact_email']??'');if($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid contact email.');
            $socials=[];foreach(social_hosts() as $name=>$hosts){$key='social_'.strtolower($name);$url=trim($_POST[$key]??'');if($url!==''&&!valid_social($name,$url))throw new RuntimeException('Use the full HTTPS '.$name.' profile URL.');$socials[$key]=$url;}
            foreach($socials as $key=>$url)save_setting($key,$url);
            foreach(['name','tagline','contact_email','newsletter_intro','name_ar','tagline_ar','newsletter_intro_ar'] as $key)if(array_key_exists($key,$_POST))save_setting($key,unicode_cut(trim($_POST[$key]),1000));done('settings','Settings saved.');
        }elseif($action==='read_message'){q('UPDATE aa_messages SET is_read=1 WHERE id=?',[(int)$_POST['id']]);done('messages','Marked read.');}
        elseif($action==='delete_message'){q('DELETE FROM aa_messages WHERE id=?',[(int)$_POST['id']]);done('messages','Message deleted.');}
        elseif($action==='delete_subscriber'){q('DELETE FROM aa_subscribers WHERE id=?',[(int)$_POST['id']]);done('subscribers','Subscriber deleted.');}
        elseif($action==='export'){
            header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="blog-subscribers.csv"');$stream=fopen('php://output','w');fputcsv($stream,['email','subscribed_at','unsubscribe_url']);foreach(q('SELECT * FROM aa_subscribers WHERE status=?',['active'])->fetchAll() as $sub){$email=$sub['email'];if(preg_match('/^[=+@\-\t\r]/',$email))$email="'".$email;fputcsv($stream,[$email,$sub['created_at'],rtrim(config()['base_url'],'/').'/api/unsubscribe.php?token='.$sub['token']]);}fclose($stream);exit;
        }elseif($action==='password'){
            if(!password_verify($_POST['current_password']??'',$user['password_hash']))throw new RuntimeException('Current password is incorrect.');
            $pw=$_POST['new_password']??'';if(strlen($pw)<12||strlen($pw)>128||$pw!==($_POST['confirm_password']??''))throw new RuntimeException('Use matching new passwords of 12–128 characters.');
            $hash=password_hash($pw,PASSWORD_DEFAULT);q('UPDATE aa_admins SET password_hash=? WHERE id=?',[$hash,$user['id']]);session_regenerate_id(true);$_SESSION['password_version']=$hash;done('account','Password updated. Other sessions will be signed out.');
        }else throw new RuntimeException('Unknown action.');
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof PDOException?'Could not save. Check that the URL slug is unique.':($e instanceof RuntimeException?$e->getMessage():'Unable to finish this action. Please retry.');}
}
