<form method="post" enctype="multipart/form-data" class="panel"><?=csrf()?><input type="hidden" name="action" value="upload"><h2>Add a photo, artwork, or book cover</h2><p class="muted">PNG, JPEG, or WebP · Up to 8 MB. Images are optimized to WebP at up to 1600 pixels.</p><label>Image file<input type="file" name="illustration" accept="image/png,image/jpeg,image/webp" required></label><button>Upload image</button></form><div class="media-grid"><?php foreach(['images','book-covers','uploads'] as $folder)foreach(glob(dirname(__DIR__).'/assets/'.$folder.'/*.webp')?:[] as $file):if(str_contains($file,'-640.'))continue;$v='assets/'.$folder.'/'.basename($file);?><article class="panel"><img src="/<?=h($v)?>" alt="<?=h(basename($file))?>"><h3><?=h(basename($file))?></h3><small><?=h($folder)?></small></article><?php endforeach?></div>
<?php elseif($section==='pages'):?><form method="post" class="panel editor"><?=csrf()?><input type="hidden" name="action" value="save_pages"><h2>Home</h2><?=field('hero_title','Headline',setting('hero_title'))?><?=area('hero_intro','Introduction',setting('hero_intro'),4)?><h2>About</h2><?=field('about_title','About headline',setting('about_title'))?><?=area('about_body','About text',setting('about_body'),14)?><h2>Work</h2><?=area('work_body','Projects',setting('work_body'),14)?><h2>Arabic pages · الصفحات العربية</h2><div dir="rtl" lang="ar"><?=field('hero_title_ar','عنوان الرئيسية',setting('hero_title_ar'))?><?=area('hero_intro_ar','مقدمة الرئيسية',setting('hero_intro_ar'),4)?><?=field('about_title_ar','عنوان صفحة عن أحمد',setting('about_title_ar'))?><?=area('about_body_ar','نبذة عن أحمد',setting('about_body_ar'),14)?><?=area('work_body_ar','المشروعات',setting('work_body_ar'),14)?></div><p class="hint">Use ## for headings and blank lines between paragraphs.</p><button>Save pages</button></form>
<?php elseif($section==='settings'):?><form method="post" class="panel editor"><?=csrf()?><input type="hidden" name="action" value="save_settings"><?=field('name','Display name',setting('name'))?><?=field('tagline','Blog description',setting('tagline'))?><?=field('contact_email','Public contact email — optional',setting('contact_email'),'email')?><?=area('newsletter_intro','Newsletter introduction',setting('newsletter_intro'),3)?><h2>Social profiles</h2><p class="hint">Paste your own profile URLs. Leave blank to show an unconfigured icon.</p><?php foreach(social_hosts() as $name=>$hosts):?><?=field('social_'.strtolower($name),$name.' profile URL',setting('social_'.strtolower($name),''),'url')?><?php endforeach?><h2>Arabic identity</h2><div lang="ar" dir="rtl"><?=field('name_ar','الاسم',setting('name_ar'))?><?=field('tagline_ar','وصف الموقع',setting('tagline_ar'))?><?=area('newsletter_intro_ar','مقدمة النشرة',setting('newsletter_intro_ar'),3)?></div><p class="hint">Messages are stored in your dashboard. Subscribers can be exported to your email provider. Automatic emails and campaign delivery are not configured.</p><button>Save settings</button></form>
<?php elseif($section==='messages'):$rows=q('SELECT * FROM aa_messages ORDER BY id DESC')->fetchAll();if(!$rows):?><section class="panel empty"><h2>No messages yet.</h2><p>Messages from your Contact form will appear here.</p></section><?php endif?><?php foreach($rows as $m):?><article class="panel message"><span class="badge"><?=$m['is_read']?'Read':'New'?></span><h2><?=h($m['name'])?></h2><a href="mailto:<?=h($m['email'])?>"><?=h($m['email'])?></a><small><?=h($m['created_at'])?> UTC</small><p class="message-text"><?=h($m['message'])?></p><div class="row-actions"><?=action_form('read_message',(int)$m['id'],'Mark read')?><?=action_form('delete_message',(int)$m['id'],'Delete',true)?></div></article><?php endforeach?>
<?php elseif($section==='subscribers'):?><div class="toolbar"><p>People who opted in to your updates.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="export"><button>Export active subscribers</button></form></div><p class="notice">Include each person’s unsubscribe link from the export when sending updates. Campaign delivery is handled separately by your email provider.</p><section class="panel"><?php foreach(q('SELECT * FROM aa_subscribers ORDER BY id DESC')->fetchAll() as $sub):?><div class="list-row"><div><h3><?=h($sub['email'])?></h3><small><?=h($sub['status'])?> · <?=h($sub['created_at'])?> UTC</small></div><?=action_form('delete_subscriber',(int)$sub['id'],'Delete',true)?></div><?php endforeach?></section>
<?php elseif($section==='seo'):?><section class="panel"><h2>Search visibility</h2><p>Pages and images have canonical URLs, language alternatives, social previews, and structured data. Search engines decide whether and when to index them.</p><p><a href="/sitemap.xml" target="_blank" rel="noopener">Open page & image sitemap ↗</a></p><p><a href="https://search.google.com/search-console" target="_blank" rel="noopener">Google Search Console ↗</a> · Verify ahmadalabbas.com using a DNS TXT record, then submit sitemap.xml.</p><p><a href="https://www.bing.com/webmasters/" target="_blank" rel="noopener">Bing Webmaster Tools ↗</a></p><h3>Keep both versions complete</h3><p>Arabic articles use the same entry as English articles. Update the translation when editing the source. Arabic and English books are independent.</p><?php $missing=q("SELECT p.title FROM aa_posts p LEFT JOIN aa_translations t ON t.post_id=p.id WHERE p.type='article' AND p.status='published' AND (t.status IS NULL OR t.status<>'published')")->fetchAll();?><p><?=count($missing)?> published articles need an Arabic translation.</p><?php foreach($missing as $m):?><p><?=h($m['title'])?></p><?php endforeach?><h3>Images</h3><p>Use accurate English and Arabic alt text in Gallery. Give every article a useful subtitle and relevant local image. Do not add keywords unrelated to the content.</p></section>
<?php elseif($section==='account'):?><form method="post" class="panel editor"><?=csrf()?><input type="hidden" name="action" value="password"><h2>Change your password</h2><?=field('current_password','Current password','','password')?><?=field('new_password','New password — at least 12 characters','','password')?><?=field('confirm_password','Confirm new password','','password')?><button>Update password</button></form><p class="muted">Signed in as <?=h($user['email'])?>. Sessions expire after 30 minutes of inactivity.</p><?php endif?>
